def try_decode(s):
    results = {}
    # utf-8 bytes misread as latin1, re-encode as utf8 -> fix: encode latin1, decode utf8
    try:
        results['latin1->utf8'] = s.encode('latin1').decode('utf-8')
    except Exception as e:
        results['latin1->utf8'] = f"ERR: {e}"
    # cp1252 variant
    try:
        results['cp1252->utf8'] = s.encode('cp1252').decode('utf-8')
    except Exception as e:
        results['cp1252->utf8'] = f"ERR: {e}"
    # shift_jis misread as latin1/cp1252, fix: encode latin1/cp1252, decode shift_jis or cp932
    try:
        results['latin1->cp932'] = s.encode('latin1').decode('cp932')
    except Exception as e:
        results['latin1->cp932'] = f"ERR: {e}"
    try:
        results['cp1252->cp932'] = s.encode('cp1252').decode('cp932')
    except Exception as e:
        results['cp1252->cp932'] = f"ERR: {e}"
    return results

for item in data:
    if item['idx'] in targets:
        print("="*20, item['idx'], item['name'])
        for field in ['title','desc']:
            s = item.get(field,'')
            if not s: continue
            print(f"-- {field} raw: {s[:80]}")
            r = try_decode(s)
            for k,v in r.items():
                print(f"   [{k}] {v[:150] if isinstance(v,str) else v}")
